args.sparql:
SELECT ?father ?fatherLabel WHERE {
  dbr:Prince_David_of_Kakheti (dbp:father|dbo:parent) ?father .
  OPTIONAL { ?father rdfs:label ?fatherLabel FILTER (lang(?fatherLabel) = 'en') }
}

SELECT DISTINCT ?deathPlace ?deathPlaceLabel WHERE {
  dbr:Teimuraz_I_of_Kakheti (dbp:deathPlace|dbo:deathPlace) ?deathPlace .
  OPTIONAL { ?deathPlace rdfs:label ?deathPlaceLabel FILTER (lang(?deathPlaceLabel) = 'en') }
}

SELECT DISTINCT ?father ?fatherLabel ?deathPlace ?deathPlaceLabel WHERE {
  dbr:Prince_David_of_Kakheti (dbp:father|dbo:parent) ?father .
  ?father (dbp:deathPlace|dbo:deathPlace) ?deathPlace .
  OPTIONAL { ?father rdfs:label ?fatherLabel FILTER(lang(?fatherLabel) = 'en') }
  OPTIONAL { ?deathPlace rdfs:label ?deathPlaceLabel FILTER(lang(?deathPlaceLabel) = 'en') }
}

