PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT DISTINCT ?father ?fatherLabel ?deathPlace ?deathPlaceLabel WHERE {
  dbr:Prince_David_of_Kakheti(dbp:father | dbo:parent) ?father .
  ?father(dbp:deathPlace | dbo:deathPlace) ?deathPlace .
  OPTIONAL {
    ?father rdfs:label ?fatherLabel
    FILTER(lang(?fatherLabel) = 'en')
  }
  OPTIONAL {
    ?deathPlace rdfs:label ?deathPlaceLabel
    FILTER(lang(?deathPlaceLabel) = 'en')
  }
}

